// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        address ownerBefore = c.owner();
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            assertTrue(false, "non-owner transfer must revert");
        } catch {
            assertEq(c.owner(), ownerBefore, "owner changed by non-owner");
        }
    }
}
